export function NavigationObserver() {
  useEffect(() => {
    const handler = () => {
      document.documentElement.dataset.direction = 'backward'
    }
    window.addEventListener('popstate', handler)
    return () => window.removeEventListener('popstate', handler)
  }, [])

  return null
}

